import java.io.Serializable;

/**
 * 地图单元格类
 * 表示游戏地图上的一个格子
 */
public class Cell implements Serializable {
    private static final long serialVersionUID = 1L;

    private int id;              // 格子ID
    private String name;         // 格子名称
    private CellType type;       // 格子类型
    private int position;        // 位置（0-39）
    private int price;           // 购买价格（适用于可购买的格子）
    private int rent;            // 基础租金
    private int housePrice;      // 建造房屋的价格
    private int houseCount;      // 已建房屋数量
    private int hotelPrice;      // 建造酒店的价格
    private Player owner;        // 所有者（如果有）
    private int colorGroup;      // 颜色组（同类颜色可以组合升级）
    private String description;  // 描述

    public Cell() {
        this.houseCount = 0;
        this.owner = null;
    }

    public Cell(int id, String name, CellType type, int position) {
        this();
        this.id = id;
        this.name = name;
        this.type = type;
        this.position = position;
    }

    // Getters and Setters
    public int getId() {
        return id;
    }

    public void setId(int id) {
        this.id = id;
    }

    public String getName() {
        return name;
    }

    public void setName(String name) {
        this.name = name;
    }

    public CellType getType() {
        return type;
    }

    public void setType(CellType type) {
        this.type = type;
    }

    public int getPosition() {
        return position;
    }

    public void setPosition(int position) {
        this.position = position;
    }

    public int getPrice() {
        return price;
    }

    public void setPrice(int price) {
        this.price = price;
    }

    public int getRent() {
        return rent;
    }

    public void setRent(int rent) {
        this.rent = rent;
    }

    public int getHousePrice() {
        return housePrice;
    }

    public void setHousePrice(int housePrice) {
        this.housePrice = housePrice;
    }

    public int getHouseCount() {
        return houseCount;
    }

    public void setHouseCount(int houseCount) {
        this.houseCount = houseCount;
    }

    public int getHotelPrice() {
        return hotelPrice;
    }

    public void setHotelPrice(int hotelPrice) {
        this.hotelPrice = hotelPrice;
    }

    public Player getOwner() {
        return owner;
    }

    public void setOwner(Player owner) {
        this.owner = owner;
    }

    public int getColorGroup() {
        return colorGroup;
    }

    public void setColorGroup(int colorGroup) {
        this.colorGroup = colorGroup;
    }

    public String getDescription() {
        return description;
    }

    public void setDescription(String description) {
        this.description = description;
    }

    /**
     * 计算当前租金
     * 租金随房屋数量增加而增加
     */
    public int calculateRent() {
        if (owner == null) {
            return 0;
        }

        int baseRent = rent;

        // 房屋租金倍数
        if (houseCount == 0) {
            return baseRent;
        } else if (houseCount < 5) {
            // 1-4个房屋：租金 = 基础租金 * (2^houseCount) * 1.5
            return (int) (baseRent * Math.pow(2, houseCount - 1) * 1.5);
        } else {
            // 酒店：最大租金
            return baseRent * 50;
        }
    }

    /**
     * 判断是否可以被购买
     */
    public boolean canBePurchased() {
        return type == CellType.EMPTY && owner == null;
    }

    /**
     * 判断是否可以被升级
     */
    public boolean canBeUpgraded() {
        return type == CellType.PROPERTY && owner != null && houseCount < 5;
    }

    /**
     * 升级房产（增加房屋）
     */
    public void upgrade() {
        if (canBeUpgraded()) {
            houseCount++;
        }
    }

    @Override
    public String toString() {
        StringBuilder sb = new StringBuilder();
        sb.append(String.format("[%d] %s (%s)", position, name, type.getDisplayName()));
        if (owner != null) {
            sb.append(String.format(" - 所属: %s", owner.getName()));
            if (houseCount > 0) {
                sb.append(String.format(" (房屋: %d)", houseCount));
            }
        }
        if (price > 0) {
            sb.append(String.format(" 价格: $%d", price));
        }
        return sb.toString();
    }
}"}

{"file_path": "/tmp/dafuhao/src/main/java/com/dafuhao/core/Player.java", "search_text": "", "replace_text": "package com.dafuhao.core;

import java.io.Serializable;
import java.util.ArrayList;
import java.util.List;
import java.util.UUID;

/**
 * 玩家类
 * 表示游戏中的一个玩家
 */
public class Player implements Serializable {
    private static final long serialVersionUID = 1L;

    private String id;              // 玩家唯一ID
    private String name;            // 玩家名称
    private String avatar;          // 头像路径
    private boolean isAI;           // 是否为AI玩家
    private int cash;               // 现金
    private int totalAssets;        // 总资产
    private int position;           // 当前位置（格子索引）
    private boolean isBankrupt;     // 是否破产
    private boolean isInPrison;     // 是否在监狱
    private int prisonTurns;        // 监狱剩余回合
    private boolean skipTurn;       // 是否跳过当前回合（住院等）
    private int consecutiveDoubles; // 连续掷出双六的次数
    private List<Cell> properties;  // 拥有的房产
    private List<String> items;     // 拥有的道具
    private int colorGroupCount;    // 完整颜色组的数量（用于计算租金加成）

    // 常量定义
    public static final int INITIAL_CASH = 2000;      // 初始资金
    public static final int PASS_START_BONUS = 200;   // 经过起点的奖励
    public static final int GO_TO_PRISON_TURNS = 3;   // 入狱轮数

    public Player() {
        this.id = UUID.randomUUID().toString();
        this.properties = new ArrayList<>();
        this.items = new ArrayList<>();
        this.cash = INITIAL_CASH;
        this.position = 0;
        this.isBankrupt = false;
        this.isInPrison = false;
        this.prisonTurns = 0;
        this.skipTurn = false;
        this.consecutiveDoubles = 0;
        this.totalAssets = 0;
        this.colorGroupCount = 0;
    }

    public Player(String name, boolean isAI) {
        this();
        this.name = name;
        this.isAI = isAI;
    }

    public Player(String name, String avatar, boolean isAI) {
        this(name, isAI);
        this.avatar = avatar;
    }

    // Getters and Setters
    public String getId() {
        return id;
    }

    public void setId(String id) {
        this.id = id;
    }

    public String getName() {
        return name;
    }

    public void setName(String name) {
        this.name = name;
    }

    public String getAvatar() {
        return avatar;
    }

    public void setAvatar(String avatar) {
        this.avatar = avatar;
    }

    public boolean isAI() {
        return isAI;
    }

    public void setAI(boolean AI) {
        isAI = AI;
    }

    public int getCash() {
        return cash;
    }

    public void setCash(int cash) {
        this.cash = cash;
    }

    public void addCash(int amount) {
        this.cash += amount;
        calculateTotalAssets();
    }

    public void deductCash(int amount) {
        this.cash -= amount;
        calculateTotalAssets();
    }

    public boolean hasEnoughCash(int amount) {
        return cash >= amount;
    }

    public int getPosition() {
        return position;
    }

    public void setPosition(int position) {
        this.position = position;
    }

    public void move(int steps) {
        int oldPosition = this.position;
        this.position = (this.position + steps) % 40;

        // 检查是否经过起点
        if (this.position < oldPosition) {
            addCash(PASS_START_BONUS);
        }
    }

    public boolean isBankrupt() {
        return isBankrupt;
    }

    public void setBankrupt(boolean bankrupt) {
        isBankrupt = bankrupt;
    }

    public void goBankrupt() {
        isBankrupt = true;
        // 清算所有房产
        for (Cell property : properties) {
            property.setOwner(null);
            property.setHouseCount(0);
        }
        properties.clear();
        cash = 0;
    }

    public boolean isInPrison() {
        return isInPrison;
    }

    public void setInPrison(boolean inPrison) {
        isInPrison = inPrison;
    }

    public void enterPrison() {
        isInPrison = true;
        prisonTurns = GO_TO_PRISON_TURNS;
        position = 10; // 监狱位置
    }

    public void leavePrison() {
        isInPrison = false;
        prisonTurns = 0;
    }

    public int getPrisonTurns() {
        return prisonTurns;
    }

    public void setPrisonTurns(int prisonTurns) {
        this.prisonTurns = prisonTurns;
    }

    public void decreasePrisonTurns() {
        if (prisonTurns > 0) {
            prisonTurns--;
            if (prisonTurns == 0) {
                leavePrison();
            }
        }
    }

    public boolean isSkipTurn() {
        return skipTurn;
    }

    public void setSkipTurn(boolean skipTurn) {
        this.skipTurn = skipTurn;
    }

    public int getConsecutiveDoubles() {
        return consecutiveDoubles;
    }

    public void setConsecutiveDoubles(int consecutiveDoubles) {
        this.consecutiveDoubles = consecutiveDoubles;
    }

    public void incrementDoubles() {
        consecutiveDoubles++;
    }

    public void resetDoubles() {
        consecutiveDoubles = 0;
    }

    public List<Cell> getProperties() {
        return properties;
    }

    public void addProperty(Cell property) {
        properties.add(property);
        calculateTotalAssets();
    }

    public void removeProperty(Cell property) {
        properties.remove(property);
        calculateTotalAssets();
    }

    public List<String> getItems() {
        return items;
    }

    public void addItem(String item) {
        items.add(item);
    }

    public void useItem(String item) {
        items.remove(item);
    }

    public boolean hasItem(String item) {
        return items.contains(item);
    }

    public int getColorGroupCount() {
        return colorGroupCount;
    }

    public void setColorGroupCount(int colorGroupCount) {
        this.colorGroupCount = colorGroupCount;
    }

    public int getTotalAssets() {
        return totalAssets;
    }

    public void setTotalAssets(int totalAssets) {
        this.totalAssets = totalAssets;
    }

    /**
     * 计算总资产
     */
    public void calculateTotalAssets() {
        int propertyValue = 0;
        for (Cell property : properties) {
            propertyValue += property.getPrice();
            propertyValue += property.getHouseCount() * property.getHousePrice();
        }
        this.totalAssets = cash + propertyValue;
    }

    /**
     * 检查玩家是否可以购买某个房产
     */
    public boolean canAfford(int price) {
        return cash >= price;
    }

    /**
     * 购买房产
     */
    public boolean purchase(Cell cell, int price) {
        if (canAfford(price) && cell.canBePurchased()) {
            deductCash(price);
            cell.setOwner(this);
            addProperty(cell);
            return true;
        }
        return false;
    }

    /**
     * 支付租金给另一个玩家
     */
    public boolean payRent(Player owner, int rent) {
        if (canAfford(rent)) {
            deductCash(rent);
            owner.addCash(rent);
            return true;
        } else {
            // 现金不够，支付全部现金并破产
            int allCash = cash;
            deductCash(allCash);
            owner.addCash(allCash);
            goBankrupt();
            return false;
        }
    }

    /**
     * 建造房屋
     */
    public boolean buildHouse(Cell property) {
        int cost = property.getHousePrice();
        if (canAfford(cost) && property.canBeUpgraded()) {
            deductCash(cost);
            property.upgrade();
            return true;
        }
        return false;
    }

    /**
     * 获取玩家的状态描述
     */
    public String getStatus() {
        StringBuilder sb = new StringBuilder();
        sb.append(name).append(" (").append(isAI ? "AI" : "人类").append(")");
        sb.append(" - 现金: $").append(cash);
        sb.append(" - 房产: ").append(properties.size()).append("处");
        if (isInPrison) {
            sb.append(" [在狱中，剩余").append(prisonTurns).append("回合]");
        }
        if (isBankrupt) {
            sb.append(" [已破产]");
        }
        return sb.toString();
    }

    @Override
    public String toString() {
        return String.format("%s [现金: $%d, 资产: $%d, 位置: %d, 房产: %d处]", 
                name, cash, totalAssets, position, properties.size());
    }

    @Override
    public boolean equals(Object obj) {
        if (this == obj) return true;
        if (obj == null || getClass() != obj.getClass()) return false;
        Player player = (Player) obj;
        return id != null && id.equals(player.id);
    }

    @Override
    public int hashCode() {
        return id != null ? id.hashCode() : 0;
    }
}"}

