    /**
     * 同时掷两个骰子
     * 返回两个骰子的点数和，以及是否为双六
     */
    public DiceResult rollTwoDice() {
        int dice1 = rollDice();
        int dice2 = rollDice();
        boolean isDoubles = (dice1 == dice2);
        return new DiceResult(dice1, dice2, dice1 + dice2, isDoubles);
    }

    /**
     * 计算从一个位置移动指定步数后的新位置
     */
    public int calculateNewPosition(int currentPosition, int steps) {
        return (currentPosition + steps) % totalCells;
    }

    /**
     * 显示棋盘信息（调试用）
     */
    public void displayBoard() {
        System.out.println("=== 游戏棋盘 ===");
        System.out.println("总格子数: " + totalCells);
        System.out.println();
        for (Cell cell : cells) {
            System.out.println(cell);
        }
    }

    /**
     * 骰子结果内部类
     */
    public static class DiceResult {
        private final int dice1;
        private final int dice2;
        private final int total;
        private final boolean isDoubles;

        public DiceResult(int dice1, int dice2, int total, boolean isDoubles) {
            this.dice1 = dice1;
            this.dice2 = dice2;
            this.total = total;
            this.isDoubles = isDoubles;
        }

        public int getDice1() {
            return dice1;
        }

        public int getDice2() {
            return dice2;
        }

        public int getTotal() {
            return total;
        }

        public boolean isDoubles() {
            return isDoubles;
        }

        @Override
        public String toString() {
            return String.format("骰子结果: [%d] + [%d] = %d %s", 
                    dice1, dice2, total, isDoubles ? "(双六!)" : "");
        }
    }
